  // relationship spec is removed; otherwise only the authored targets are
  // cleared (the spec, and thus the relationship, remains).
  private _clearRel(relName: string, removeSpec: boolean): boolean {
    const relPath = `${this._prim.path}.${relName}`
    const layer = this._stage.getEditTarget().getLayer()!
    if (removeSpec) layer._deleteSpec(relPath)
    else layer.eraseField(relPath, 'targetPaths')
    return true
  }

  private _targets(primPath: string, relName: string): string[] {
    return this._stage.getPrim(primPath)?.getAttr(relName)?.getTargets() ?? []
  }
