// UsdShadeCoordSysAPI — binds named coordinate-system spaces onto prims.
// Reference: pxr/usd/usdShade/coordSysAPI.cpp (authoritative).
//
// Two shapes share this one class, mirroring the upstream header:
//
//   * Multi-apply (the current schema): a CoordSysAPI INSTANCE is applied to a
//     prim, recorded in apiSchemas as `CoordSysAPI:<instanceName>`, and its
//     binding lives in the relationship `coordSys:<instanceName>:binding`.
//     Each binding forwards to ONE coordinate-system prim (its first target).
//   * Deprecated (non-applied, legacy): bindings are relationships named
//     `coordSys:<name>` directly (no `:binding` suffix, no apiSchemas).
//
// A Binding is the (name, bindingRelPath, coordSysPrimPath) triple upstream's
// UsdShadeCoordSysAPI::Binding carries: the binding's base name, the path of
// the relationship that holds it, and the forwarded coordinate-system prim.
//
// For the multi-apply form `name` is GetBindingBaseName(relName) — the rel name
// with the leading `coordSys:` namespace stripped (e.g.
// `coordSys:worldSpace:binding` -> `worldSpace:binding`). For the deprecated
// form `name` is the relationship's base name (last namespace component, e.g.
// `coordSys:worldSpace` -> `worldSpace`).


// UsdShadeTokens->coordSys and the multi-apply API schema family name.
const COORD_SYS = 'coordSys'
const API_SCHEMA = 'CoordSysAPI'

export interface Binding {
  name: string
  bindingRelPath: string
  coordSysPrimPath: string
}

const EMPTY_BINDING: Binding = { name: '', bindingRelPath: '', coordSysPrimPath: '' }

function parentPath(p: string): string | null {
  if (p === '/' || !p.startsWith('/')) return null
  const i = p.lastIndexOf('/')
  return i === 0 ? '/' : p.slice(0, i)
}

// The multi-apply binding relationship name for an instance
// (_GetNamespacedPropertyName(name, coordSys:__INSTANCE_NAME__:binding)).
function bindingRelName(instanceName: string): string {
  return `${COORD_SYS}:${instanceName}:binding`
}

// The deprecated, non-applied binding relationship name
// (UsdShadeCoordSysAPI::GetCoordSysRelationshipName).
function coordSysRelName(name: string): string {
  return `${COORD_SYS}:${name}`
}

// SdfPath::StripPrefixNamespace(bindingName, coordSys).first — strips the
// leading `coordSys:` prefix (UsdShadeCoordSysAPI::GetBindingBaseName).
function stripCoordSysPrefix(relName: string): string {
  const pfx = `${COORD_SYS}:`
  return relName.startsWith(pfx) ? relName.slice(pfx.length) : relName
}

// The last namespace component (Relationship::GetBaseName), used as the
// deprecated binding `name`.
function lastNameComponent(propName: string): string {
  const i = propName.lastIndexOf(':')
  return i < 0 ? propName : propName.slice(i + 1)
}

// The multi-apply instance names applied on the prim, in apiSchemas order
// (UsdAPISchemaBase::_GetMultipleApplyInstanceNames for the CoordSysAPI type).
function coordSysInstanceNames(schemas: string[]): string[] {
  const pfx = `${API_SCHEMA}:`
  const out: string[] = []
  for (const s of schemas) if (s.startsWith(pfx)) out.push(s.slice(pfx.length))
  return out
}
